const cfg=window.TT_TRADING_CONFIG,$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=v=>v===null||v===undefined?'Missing':Number(v).toLocaleString('en-PK',{maximumFractionDigits:2});
