function msg(v,bad=false){$('dtMessage').textContent=v;$('dtMessage').className=bad?'error':'';}
function field(label,name,value='',type='number',attrs=''){return '<label>'+esc(label)+'<input name="'+name+'" type="'+type+'" '+(type==='number'?'step="any" ':'')+'value="'+esc(value??'')+'" '+attrs+'></label>';}
function select(label,name,items,value=''){return '<label>'+esc(label)+'<select name="'+name+'">'+items.map(x=>{const [v,t]=Array.isArray(x)?x:[x,x];return '<option value="'+esc(v)+'" '+(String(value)===String(v)?'selected':'')+'>'+esc(t)+'</option>';}).join('')+'</select></label>';}
function fields(form){return Object.fromEntries(new FormData(form));}
async function api(body){const url='/api/directors_trading.php?'+(cfg.loadingOnly?'origin=exports&':cfg.costOnly?'area=costing&':cfg.origin==='Accounts'?'origin=accounts&':'')+'entity='+encodeURIComponent($('dtEntity').value)+'&asOf='+encodeURIComponent($('dtDate').value);let r;try{r=await fetch(url,body?{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({...body,entity:$('dtEntity').value,asOf:$('dtDate').value,csrf:cfg.csrf})}:{credentials:'same-origin'});}catch{throw Error('Connection interrupted. Your figures are retained. Check your connection and try again; no save is confirmed.');}let d;try{d=await r.json();}catch{throw Error('Server did not confirm the response. Reopen and check before retrying.');}if(!r.ok||!d.ok)throw Error(d.error||'Request failed.');return d;}
async function load(){if(busy)return;if(dirty&&!confirm('Discard unsaved edits and open the latest saved data?'))return;busy=true;msg('Loading saved sources…');try{data=await api();dirty=false;costDraft=null;selectedId=new URLSearchParams(location.search).get('deal')||'';render();msg('Loaded saved records through '+data.asOf+'.');}catch(e){msg(e.message,true);}finally{busy=false;}}
async function save(body,key){if(busy)return;if($('dtEntity').value!==data.entity||$('dtDate').value!==data.asOf){msg('Use Open / Refresh after changing company or posting date before saving this form.',true);return false;}busy=true;$('dtWorkspace').inert=true;$('dtEntity').disabled=true;$('dtDate').disabled=true;msg('Saving…');const signature=JSON.stringify(body);if(!keys.has(key)||keys.get(key).signature!==signature)keys.set(key,{signature,requestKey:crypto.randomUUID()});try{data=await api({...body,requestKey:keys.get(key).requestKey});dirty=false;keys.delete(key);render();msg(data.result?.postId?'Posted '+data.result.postId+'.':'Saved.');return true;}catch(e){msg(e.message,true);return false;}finally{busy=false;$('dtWorkspace').inert=false;$('dtEntity').disabled=false;$('dtDate').disabled=false;}}
function print(title,party='',ref=''){document.body.classList.toggle('printCosting',tab==='costing');const old=document.title;document.title=window.TT_DOCUMENT_NAME?.name({company:data.entity,party,title,reference:ref,date:data.asOf})||[party,title,ref,data.asOf].filter(Boolean).join(' - ');window.addEventListener('afterprint',()=>{document.title=old;},{once:true});window.print();document.title=old;}
function render(){if(!data)return;clearTimeout(previewTimer);++previewSequence;if(cfg.loadingOnly){renderLoadingOnly();return;}if(cfg.costOnly){if(!['costing','rules'].includes(tab))tab='costing';$('dtTabs').hidden=true;}$('dtTabs').querySelectorAll('button').forEach(b=>b.classList.toggle('selected',b.dataset.tab===tab));if(tab==='costing')renderCosting();else if(tab==='cashflow')renderCashflow();else if(tab==='rules')renderRules();else renderDeals();window.TT_FORM_VIEWPORT?.open($('dtWorkspace'));}
