function paymentForm(d,advance=false){$('dtDetail').innerHTML='<section class="section"><h2>'+esc(advance?'Advance received from ':d.bookBalancePKR>0?'Receive from ':'Pay ')+esc(d.party)+'</h2><form id="dtPaymentForm"><div class="grid">'+field(advance?'Advance actually received (PKR)':'Part / full book balance to clear (PKR)','amountPKR',advance?'':Math.abs(d.bookBalancePKR),'number','required min="0.01"')+select('Cash / bank','bankId',[['CASH|'+data.entity,'Company petty cash'],...data.banks.map(b=>[b.id,b.label])])+field('Payment / receipt reference','reference','','text','required')+'</div><div id="dtForeignPayment" class="grid" hidden>'+field('Amount in bank currency','nativeAmount','','number','min="0.01"')+field('Actual exchange rate (PKR per bank currency)','exchangeRate','','number','min="0.000001"')+'<p>The conversion difference is recorded automatically as realized exchange gain / loss.</p></div><div class="toolbar"><button>Post '+esc(advance||d.bookBalancePKR>0?'receipt':'payment')+'</button></div></form></section>';const form=$('dtPaymentForm'),sync=()=>{const bank=data.banks.find(b=>b.id===form.elements.bankId.value),foreign=!!bank&&bank.currency!=='PKR';$('dtForeignPayment').hidden=!foreign;['nativeAmount','exchangeRate'].forEach(k=>{form.elements[k].required=foreign;form.elements[k].disabled=!foreign;});if(foreign)form.elements.nativeAmount.closest('label').firstChild.textContent='Amount in '+bank.currency;};form.elements.bankId.onchange=sync;sync();form.onsubmit=e=>{e.preventDefault();save({...fields(form),action:advance?'advance':'payment',id:d.id,version:d.version},advance?'advance':'payment');};window.TT_FORM_VIEWPORT?.open($('dtDetail'));}
function initialCost(){const p=structuredClone(data.profiles[0]);return applyDailyRates({...p,profileId:p.id,id:undefined,date:data.asOf,quantityMT:1,fx:data.dailyRates?.fx??'',whtPct:1.25,bankPct:0.1,incoterm:'FOB',packing:'50 kg PP',packingAdjustment:0,packingCurrency:'USD',masterBagUSDPerMT:packingDefault('50 kg PP')?.masterBagAmount??'',payloadMT:27,thcUSDPerMT:0,freightUSDPerContainer:'',insuranceUSDPerMT:'',finance:{enabled:false,dayBasis:365,feesPKR:0,allocationPct:100}});}
function applyDailyRates(c){const r=data.dailyRates;if(!r)return c;c.dailyRateDate=r.date;c.dailyRateVersion=r.version;c.fx=r.fx??c.fx;const factor={KG:1,MAUND:40,MT:1000};if(/^IRRI-6/i.test(c.name||'')){const ratio=factor[c.purchaseUnit]/factor[r.purchaseUnit||'KG'];if(r.cashPrice!=null)c.cashPrice=r.cashPrice*ratio;if(r.creditPrice!=null)c.creditPrice=r.creditPrice*ratio;if(r.brokenPrice!=null)for(const o of c.outputs)if(o.product==='B2')o.ratePKRPerKg=r.brokenPrice/factor[r.brokenUnit||'KG'];}else if(c.profileId==='BROKEN-OWN'&&r.brokenPrice!=null)c.cashPrice=r.brokenPrice*factor[c.purchaseUnit]/factor[r.brokenUnit||'KG'];return c;}
function packingDefault(name){return (data.packingDefaults||[{name:'50 kg PP',amount:0,version:0},{name:'25 kg PP',amount:3,version:0}]).find(p=>p.name===name);}
function costField(label,name,c,type='number',attrs=''){return field(label,name,c[name],type,attrs);}
