 function paint(result){$('dtPurchaseSummary').textContent='Purchase: cash '+money(c.cashPrice)+' / udhaar '+(c.creditPrice===''||c.creditPrice==null?'not set':money(c.creditPrice))+' PKR/'+({KG:'kg',MAUND:'40 kg',MT:'MT'}[c.purchaseUnit]||'kg')+(c.dailyRateDate?' · rate date '+c.dailyRateDate:' · saved recipe assumptions');$('dtLiveCost').innerHTML=[['cash','Cash'],['udhaar','Udhaar'],['financedCash','Cash + financing']].filter(([k])=>k!=='financedCash'||c.finance?.enabled).map(([k,title])=>'<div class="costResult"><span>'+title+'</span><strong>'+ (k==='financedCash'&&!c.finance?.enabled?'—':result.costs[k]?money(result.costs[k].costUSDPerMT):'—')+' <small>USD/MT</small></strong><span>'+ (k==='financedCash'&&!c.finance?.enabled?'Financing is off':result.costs[k]?money(result.costs[k].costPKRPerMT)+' PKR/MT':'Enter udhaar purchase rate')+'</span></div>').join('')+'<details><summary>Cost breakdown</summary><dl class="costBreakdown"><dt>Net exchange rate</dt><dd>'+money(result.effectiveFX)+'</dd><dt>Milling PKR/input kg</dt><dd>'+money(result.millingPKRPerInputKg||0)+'</dd><dt>Processing PKR/input kg</dt><dd>'+money(result.processingPKRPerInputKg||0)+'</dd><dt>Material PKR/MT</dt><dd>'+money(result.costs.cash.materialPKRPerMT)+'</dd><dt>By-product credit / input MT</dt><dd>'+money(result.byproductCreditPKRPerInputMT)+'</dd><dt>Bank financing PKR</dt><dd>'+money(result.finance.costPKR)+'</dd></dl></details>';$('dtPreviewStatus').textContent='Up to date · not saved';$('dtPreviewStatus').className='';}
 function preview(){toggle();collect();delete c.calculation;clearTimeout(previewTimer);const sequence=++previewSequence;$('dtSavedState').textContent='Unsaved changes · Save when ready';$('dtPreviewStatus').textContent='Updating…';$('dtLiveCost').innerHTML='<p class="muted">Updating costs…</p>';previewTimer=setTimeout(async()=>{try{if($('dtEntity').value!==data.entity||$('dtDate').value!==data.asOf)throw Error('Refresh saved data for the selected company and date.');const r=window.TT_COSTING_ENGINE?{calculation:window.TT_COSTING_ENGINE.calculate(c,data)}:await api({action:'preview_costing',input:c});if(sequence!==previewSequence||!$('dtLiveCost'))return;c.calculation=r.calculation;paint(r.calculation);}catch(e){if(sequence!==previewSequence||!$('dtLiveCost'))return;delete c.calculation;$('dtLiveCost').innerHTML='<p class="dtError">'+esc(e.message)+'</p>';$('dtPreviewStatus').textContent='Check costing inputs';$('dtPreviewStatus').className='dtError';}},180);}
