 form.onsubmit=e=>{e.preventDefault();collect();costDraft={...c};const preset=packingDefault(c.packing);const packingDefaultChange=c.packingCurrency==='USD'&&(c.packingDifferenceEnabled&&Number(c.packingAdjustment)!==Number(preset?.amount)||c.masterBagEnabled&&Number(c.masterBagUSDPerMT)!==Number(preset?.masterBagAmount))?{name:c.packing,amount:c.packingDifferenceEnabled?c.packingAdjustment:(preset?.amount??0),masterBagAmount:c.masterBagEnabled?c.masterBagUSDPerMT:preset?.masterBagAmount,version:preset?.version??0,date:data.asOf}:null;save({action:'save_costing',input:c,packingDefault:packingDefaultChange,...(c.id&&c.version?{id:c.id,version:c.version}:{})},'costing').then(ok=>{if(ok&&data.result?.calculation){const saved=data.costings.find(x=>x.id===data.result.id);costDraft={...saved.input,id:saved.id,version:saved.version,calculation:saved.calculation,date:saved.date};renderCosting();}});};
