 $('dtAddPacking').onclick=()=>{collect();const dialog=document.createElement('dialog');dialog.className='directorRatesDialog';dialog.innerHTML='<form><h2>Add packing</h2><div class="dailyRateForm">'+field('Packing name','packingName','','text','required maxlength="100"')+field('Additional USD/MT','amount','','number','required min="0"')+field('Master bag additional USD/MT (optional)','masterBagAmount','','number','min="0"')+'</div><p role="alert"></p><div class="toolbar"><button type="button" data-cancel>Cancel</button><button>Save packing</button></div></form>';document.body.append(dialog);dialog.querySelector('[data-cancel]').onclick=()=>{dialog.close();dialog.remove();};let requestKey=crypto.randomUUID();dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,values=Object.fromEntries(new FormData(form)),button=form.querySelector('button:not([type=button])');button.disabled=true;try{const saved=await window.TT_DIRECTOR_RATES.call(data.asOf,{action:'save_packing',name:values.packingName,amount:values.amount,masterBagAmount:values.masterBagAmount,date:data.asOf,version:0,csrf:cfg.csrf,requestKey});data.packingDefaults=saved.packings;c.packing=saved.result.name;c.packingAdjustment=saved.result.amount;c.masterBagUSDPerMT=saved.result.masterBagAmount;c.packingDifferenceEnabled=true;dialog.close();dialog.remove();dirty=true;renderCosting();}catch(error){form.querySelector('[role=alert]').textContent=error.message;}finally{button.disabled=false;}};dialog.showModal();};
