function renderLoadingOnly(){$('dtTabs').hidden=true;$('dtWorkspace').innerHTML='<h2>Other-exporter invoice quantities</h2><p>Record the actual invoice and contribution. Our own dispatch stays in Milling; other exporters’ goods never enter our stock. Directors reviews all prices and settlements.</p><form id="dtExportLoad"><div class="grid">'+select('Exporter agreement','id',[['','Select agreement'],...data.deals.map(d=>[d.id,d.party+' · '+(d.reference||d.id)+' · '+(d.direction==='PURCHASE'?'Our shipment':'Their shipment')])])+select('Our saved commercial invoice','shipmentId',[['','Select invoice'],...data.lots.map(l=>[l.id,l.contract+' · '+l.invoice+' · '+l.quantityMT+' MT'])])+field('Other exporter invoice reference','invoiceRef','','text')+field('Whole commercial invoice MT','totalInvoiceMT')+field('Contributor actual MT','quantityMT','','number','required min="0.000001"')+field('Actual loading date','date',data.asOf,'date','required')+'</div><div class="toolbar"><button '+(!data.canEdit?'disabled':'')+'>Save invoice contribution</button></div></form>';
const form=$('dtExportLoad');function toggle(){const d=data.deals.find(d=>d.id===form.elements.id.value),sale=d?.direction==='SALE';for(const name of ['invoiceRef','totalInvoiceMT']){form.elements[name].closest('label').hidden=!sale;form.elements[name].disabled=!sale;form.elements[name].required=sale;}form.elements.shipmentId.closest('label').hidden=sale;form.elements.shipmentId.disabled=sale;form.elements.shipmentId.required=!!d&&!sale;}form.elements.id.onchange=toggle;toggle();form.onsubmit=e=>{e.preventDefault();const b=fields(form),d=data.deals.find(d=>d.id===b.id);if(!d){msg('Select an exporter agreement.',true);return;}save({...b,action:'loading',version:d.version,adjustments:[],externalExpenses:[]},'export-loading');};}
function renderCashflow(){$('dtWorkspace').innerHTML='<h2>Exporter cash flow</h2><p>Positive figures are receivable; negative figures are payable. Posted balances already belong to Accounts. Forecast-only amounts are additional estimates.</p>'+table(['Fellow exporter','Posted outstanding PKR','Additional forecast PKR','Total expected PKR'],data.cashflow.map(r=>'<tr><td>'+esc(r.party)+'<br>'+esc(r.direction)+'</td><td>'+money(r.bookBalancePKR)+'</td><td>'+money(r.forecastOnlyPKR)+'</td><td>'+money(r.totalExpectedPKR)+'</td></tr>'))+'<a href="/accounts/group-management.php?kind=DAILY&origin=directors">Open group daily banks, stock and external coverage</a><div class="toolbar"><button id="dtCashPrint">Print cash flow</button></div>';$('dtCashPrint').onclick=()=>print('Exporter cash flow');}
function renderRules(){$('dtWorkspace').innerHTML='<button type="button" id="dtBackCosting">← Back to costing</button><h2>Dated costing assumptions</h2><p>Enter a new effective date when WHT or bank assumptions change. Existing costings retain their saved figures. Actual tax postings continue to use their transaction-specific accounting rules and bank advice.</p>'+table(['Effective from','WHT %','Other bank %','Change reference'],data.rules.map(r=>'<tr><td>'+esc(r.effectiveFrom)+'</td><td>'+money(r.whtPct)+'</td><td>'+money(r.bankPct)+'</td><td>'+esc(r.reason)+'</td></tr>'))+'<form id="dtRuleForm"><div class="grid">'+field('Effective from','effectiveFrom',data.asOf,'date','required')+field('WHT assumption %','whtPct',1.25,'number','required')+field('Other bank deductions %','bankPct','','number','required')+field('Change reference / reason','reason','','text','required')+'</div><div class="toolbar"><button '+(!data.canCreate?'disabled':'')+'>Save new dated rule</button></div></form>';$('dtBackCosting').onclick=()=>{tab='costing';render();};$('dtRuleForm').onsubmit=e=>{e.preventDefault();save({action:'save_rule',...fields(e.currentTarget)},'rule');};}
